'use strict';
// Read the returned findings without upgrading missing fields into conclusions.
const buaBase={resultContent,modalContent,handleAction,exportRows,doExport,closeModal};
const buaViews=new Map();
const BUA_MODES={tender:'招标文件分析',bid:'投标文件分析',joint:'招投标联合分析',unknown:'环节未注明'};
const BUA_STATES={review:'待核验',insufficient:'资料不足',none:'未发现明显线索',notApplicable:'不适用',failed:'分析失败',pending:'待返回'};
let buaSourceReturn=null;
function buaView(t){if(!buaViews.has(t.id)){if(buaViews.size>=24)buaViews.delete(buaViews.keys().next().value);buaViews.set(t.id,{tab:'findings',project:'all',mode:'all',status:'all',risk:'all',file:'all',query:'',page:1,size:20,filePage:1});}return buaViews.get(t.id);}
function buaActive(){return state.view==='tool'&&state.toolId==='bidding'&&!!currentTask()&&!trMode();}
function buaMode(r,t){const raw=r.mode||r.analysis_mode||r.analysisMode,alias={bidding_only:'tender',tender_only:'bid',joint_only:'joint',both:'joint'};if(raw)return alias[raw]||(['tender','bid','joint'].includes(raw)?raw:'unknown');const kind=r.docType||r.doc_type;if(kind)return {bidding:'tender',tender:'bid',joint:'joint'}[kind]||'unknown';if(r.check==='资格条件与评分')return 'tender';if(r.check==='投标响应完整性')return 'bid';if(r.check==='招投标响应对照')return 'joint';return t.modes?.length===1?t.modes[0]:'unknown';}
function buaRisk(r){const raw=r.riskLevel??r.risk_level,values={high:'high',medium:'medium',low:'low',none:'none','高':'high','高风险':'high','中':'medium','中风险':'medium','低':'low','低风险':'low','无':'none','未发现风险':'none'};return values[raw]||null;}
function buaRiskText(r){const k=buaRisk(r);return k?{high:'高风险',medium:'中风险',low:'低风险',none:'未发现风险'}[k]:'未返回风险等级';}
function buaConfidence(r){const n=r.confidence;return n!==null&&n!==undefined&&n!==''&&Number.isFinite(Number(n))?String(n)+'%':'未返回';}
function buaProject(t,r){const explicit=r.projectId||r.project_id;return (t.projects||[]).find(p=>explicit&&String(p.id)===String(explicit))||(t.projects||[]).find(p=>p.name===(r.projectName||r.project_name||r.title))||(t.projects||[]).find(p=>(p.tender||[]).includes(r.doc)||(p.bidders||[]).some(b=>(b.files||[]).includes(r.doc)))||null;}
function buaProjectFiles(p){return p?[...(p.tender||[]),...(p.bidders||[]).flatMap(b=>b.files||[])]:[];}
function buaResolveSource(t,entry,side=''){const raw=side?entry?.['file'+side]:entry?.file,nested=raw&&typeof raw==='object'?raw:{},lower=side.toLowerCase(),ids=side?[entry?.['file'+side+'Uuid'],entry?.['file'+side+'Id'],entry?.['file_'+lower+'_uuid'],entry?.['file_'+lower+'_id'],entry?.['document_'+lower+'_id'],entry?.['source'+side+'Id']]:[entry?.file_uuid,entry?.fileUuid,entry?.fileId,entry?.file_id,entry?.documentId,entry?.document_id,entry?.sourceId,entry?.doc];ids.push(nested.file_uuid,nested.fileUuid,nested.fileId,nested.file_id,nested.documentId,nested.document_id,nested.id);const id=ids.find(value=>value!==undefined&&value!==null&&value!==''&&(typeof value==='string'||typeof value==='number'));if(id!==undefined)return[String(id)];if(typeof raw==='string'&&(t.ids||[]).includes(raw))return[raw];const name=side?(typeof raw==='string'?raw:nested.file_name||nested.fileName||nested.name):entry?.fileName||entry?.file_name||nested.file_name||nested.fileName||nested.name;return name?(t.ids||[]).filter(id=>file(id)?.name===name):[];}
function buaSources(t,r){const input=[r.doc,...(r.refs||[]),...(r.docs||[]),...(r.sourceIds||[])].filter(x=>typeof x==='string'&&x),evidence=r.evidenceList||r.evidence_list||Array.isArray(r.evidence)&&r.evidence||[];for(const e of evidence)input.push(...buaResolveSource(t,e));const cards=(r.llmEvidence||r.llm_evidence)?.cards||[];for(const card of cards)input.push(...buaResolveSource(t,card),...buaResolveSource(t,card,'A'),...buaResolveSource(t,card,'B'));return [...new Set(input.length?input:buaProjectFiles(buaProject(t,r)))];}
function buaReadable(t,r,downloadable=false){const ids=buaSources(t,r);return (ids.length?ids:t.ids||[]).every(id=>(t.ids||[]).includes(id)&&file(id)&&auditFileAccess(file(id)).read&&(!downloadable||auditFileAccess(file(id)).download));}
function buaState(r){const raw=String(r.findingStatus||r.finding_status||r.status||'').toLowerCase();if(/fail|error/.test(raw))return 'failed';if(/running|pending|queued/.test(raw))return 'pending';if(/not_applicable/.test(raw)||/不适用/.test(r.judgment||''))return 'notApplicable';if(/insufficient|资料不足/.test(raw)||/资料不足|依据不足|无法判断/.test(r.judgment||''))return 'insufficient';if(raw==='nohit'||raw==='none'||buaRisk(r)==='none'||/未发现风险|未发现明显线索/.test(r.judgment||''))return 'none';return 'review';}
function buaRow(t,r,index){const p=buaProject(t,r),mode=buaMode(r,t),ruleId=r.ruleId??r.rule_id??'',rule=r.ruleName||r.rule_name||r.check||'规则未注明',title=r.findingTitle||r.resultTitle||r.title&&r.title!==p?.name&&r.title||rule,summary=[r.description,r.detailDescription,r.summary,r.detail,r.detail?.summary,r.detail?.description,r.aiSummary].find(value=>typeof value==='string'&&value.trim())||'';return{raw:r,index,project:p?.name||r.projectName||r.project_name||'项目未注明',projectId:p?String(p.id):'unknown',mode,ruleId,rule,title,unit:r.unit||(r.involvedUnits||r.involved_units||[]).join('、')||'未注明',status:buaState(r),risk:buaRisk(r),summary,excerpt:r.excerpt||'',sources:buaSources(t,r)};}
function buaRows(t,scope='all',downloadable=false){return (t.result||[]).map((r,i)=>buaRow(t,r,i)).filter(r=>buaReadable(t,r.raw,downloadable)&&(scope==='all'||r.sources.includes(scope)));}
function buaFiltered(t){const v=buaView(t),q=v.query.trim().toLowerCase();return buaRows(t).filter(r=>(v.project==='all'||r.projectId===v.project)&&(v.mode==='all'||r.mode===v.mode)&&(v.status==='all'||r.status===v.status)&&(v.risk==='all'||v.risk==='unknown'&&!r.risk||r.risk===v.risk)&&(v.file==='all'||r.sources.includes(v.file))&&(!q||[r.project,r.title,r.rule,r.ruleId,r.unit,r.summary,r.excerpt].join(' ').toLowerCase().includes(q)));}
function buaStatusMarkup(r){return '<span class="bua-state bua-'+r.status+'">'+BUA_STATES[r.status]+'</span>'+(r.risk?'<small class="bua-risk bua-risk-'+r.risk+'">'+buaRiskText(r.raw)+'</small>':'<small class="bua-missing">风险等级未返回</small>');}
function buaHeader(t){const v=buaView(t),rows=buaRows(t),restricted=(t.result||[]).length-rows.length;return '<div class="bua-tabs" role="tablist" aria-label="招投标分析成果">'+[['findings','检查结果'],['files','分析资料'],['report','分析报告']].map(([id,label])=>'<button role="tab" aria-selected="'+(v.tab===id)+'" class="'+(v.tab===id?'active':'')+'" data-action="bua-tab" data-tab="'+id+'">'+label+'</button>').join('')+'</div>'+(restricted?'<p class="bua-restricted" role="status">'+restricted+' 条结果的关联资料不可查看，已隐藏对应内容。</p>':'');}
function buaFindingTable(t){const v=buaView(t),rows=buaFiltered(t),pages=Math.max(1,Math.ceil(rows.length/v.size));v.page=Math.min(v.page,pages);const start=(v.page-1)*v.size;return '<div class="bua-table-scroll"><table class="bua-table"><thead><tr><th>项目 / 涉及单位</th><th>检查内容</th><th>核验状态</th><th>分析摘要</th><th>操作</th></tr></thead><tbody>'+rows.slice(start,start+v.size).map(r=>'<tr><td><b>'+E(r.project)+'</b><small>'+E(r.unit)+'</small></td><td><b>'+E(r.title)+'</b><small>'+E(BUA_MODES[r.mode])+' · '+E(r.rule)+(r.ruleId?'（'+E(String(r.ruleId))+'）':'')+'</small></td><td>'+buaStatusMarkup(r)+'</td><td><div class="bua-clamp">'+E(r.summary||'本条未返回分析摘要，请查看详情和原文。')+'</div></td><td><div class="bua-row-actions">'+A('查看详情','bua-detail','data-index="'+r.index+'"')+A('查看证据','bua-evidence','data-index="'+r.index+'"')+'</div></td></tr>').join('')+'</tbody></table>'+(!rows.length?'<div class="bua-empty">当前条件下没有可查看结果。'+(v.query||v.project!=='all'||v.mode!=='all'||v.status!=='all'?'<br>'+A('清除筛选','bua-reset'):'')+'</div>':'')+'</div><div class="bua-pager"><span>共 <strong>'+rows.length+'</strong> 条</span><label>每页 <select aria-label="每页检查结果数" data-bua-change="size">'+[20,50,100].map(n=>'<option value="'+n+'" '+(v.size===n?'selected':'')+'>'+n+'</option>').join('')+'</select> 条</label><div>'+B('上一页','bua-page','sm','data-step="-1" '+(v.page<=1?'disabled':''))+'<span>第 '+v.page+' / '+pages+' 页</span>'+B('下一页','bua-page','sm','data-step="1" '+(v.page>=pages?'disabled':''))+'</div></div>';}
function buaFindings(t){const v=buaView(t),all=buaRows(t),projects=[...new Map(all.map(r=>[r.projectId,r.project])).entries()],modes=[...new Set(all.map(r=>r.mode))],counts=Object.fromEntries(Object.keys(BUA_STATES).map(k=>[k,all.filter(r=>r.status===k).length]));return '<section class="bua-findings"><div class="bua-states"><button class="'+(v.status==='all'?'active':'')+'" data-action="bua-status" data-status="all">全部结果 <strong>'+all.length+'</strong></button>'+Object.entries(BUA_STATES).filter(([k])=>counts[k]||v.status===k).map(([k,label])=>'<button class="'+(v.status===k?'active':'')+'" data-action="bua-status" data-status="'+k+'">'+label+' <strong>'+counts[k]+'</strong></button>').join('')+'</div><div class="bua-filters"><select aria-label="按项目筛选检查结果" data-bua-change="project"><option value="all">全部项目</option>'+projects.map(([id,name])=>'<option value="'+E(id)+'" '+(v.project===id?'selected':'')+'>'+E(name)+'</option>').join('')+'</select><select aria-label="按分析环节筛选" data-bua-change="mode"><option value="all">全部分析环节</option>'+modes.map(k=>'<option value="'+k+'" '+(v.mode===k?'selected':'')+'>'+BUA_MODES[k]+'</option>').join('')+'</select><select aria-label="按风险等级筛选" data-bua-change="risk"><option value="all">全部风险等级</option>'+[['high','高风险'],['medium','中风险'],['low','低风险'],['none','未发现风险'],['unknown','风险等级未返回']].map(([k,n])=>'<option value="'+k+'" '+(v.risk===k?'selected':'')+'>'+n+'</option>').join('')+'</select><div class="search">'+I('search','icon-sm')+'<input id="bua-query" data-bua-input="query" aria-label="搜索招投标检查结果" placeholder="搜索检查内容、单位或原文" value="'+E(v.query)+'"></div>'+A('重置','bua-reset')+'</div>'+(v.file!=='all'?'<div class="bua-file-filter">来源文件：'+E(file(v.file)?.name||'资料不可用')+' '+A('取消文件筛选','bua-clear-file')+'</div>':'')+'<p class="bua-reading-note">点击“查看证据”，对照来源原文核验。</p><div id="bua-result-list" class="bua-result-list">'+buaFindingTable(t)+'</div></section>';}
function buaFileRole(t,id){return (t.projects||[]).flatMap(p=>[(p.tender||[]).includes(id)?p.name+' / 招标文件':null,...(p.bidders||[]).filter(b=>(b.files||[]).includes(id)).map(b=>p.name+' / '+(b.name||'未命名单位'))]).filter(Boolean).join('；')||'角色未注明';}
function buaFiles(t){const v=buaView(t),ids=(t.ids||[]).filter(id=>file(id)&&auditFileAccess(file(id)).read),pages=Math.max(1,Math.ceil(ids.length/20));v.filePage=Math.min(v.filePage,pages);return '<section class="bua-files"><p class="bua-reading-note">按项目核对本次资料，可查看原文、解析内容及该文件关联的检查结果。</p><div class="bua-table-scroll"><table class="bua-table bua-file-table"><thead><tr><th>文件名称</th><th>项目 / 资料角色</th><th>本次分析状态</th><th>操作</th></tr></thead><tbody>'+ids.slice((v.filePage-1)*20,v.filePage*20).map(id=>'<tr><td>'+E(file(id).name)+'</td><td>'+E(buaFileRole(t,id))+'</td><td>'+E((t.failedIds||[]).includes(id)?'分析失败':(t.successIds||[]).includes(id)?'已返回结果':'未返回结果')+'</td><td><div class="bua-row-actions">'+A('原文与解析','bua-source','data-id="'+E(id)+'"')+A('提取信息','bua-file-info','data-id="'+E(id)+'"')+A('相关结果','bua-file-results','data-id="'+E(id)+'"')+'</div></td></tr>').join('')+'</tbody></table></div><div class="bua-pager"><span>共 '+ids.length+' 份可查看资料</span><div>'+B('上一页','bua-file-page','sm','data-step="-1" '+(v.filePage===1?'disabled':''))+'<span>第 '+v.filePage+' / '+pages+' 页</span>'+B('下一页','bua-file-page','sm','data-step="1" '+(v.filePage===pages?'disabled':''))+'</div></div></section>';}
function buaReportBody(t){const rows=buaRows(t),group=k=>rows.filter(r=>r.status===k);return '<article class="bua-report-paper"><h2>招投标审计核查清单</h2><p>分析记录：'+E(t.name)+'</p><p>本次可查看 <strong>'+rows.length+'</strong> 条结果，涉及 <strong>'+new Set(rows.map(r=>r.projectId)).size+'</strong> 个项目。按已返回内容整理，未补充风险等级或分析结论。</p>'+Object.entries(BUA_STATES).filter(([k])=>group(k).length).map(([k,label])=>'<section><h3>'+label+' · '+group(k).length+' 条</h3>'+group(k).map(r=>'<div class="bua-report-item"><h4>'+E(r.title)+'</h4><p>'+E(r.project)+' · '+E(BUA_MODES[r.mode])+' · '+E(r.unit)+'</p><p>检查规则：'+E(r.rule)+'</p><p>'+E(r.summary||'未返回分析摘要')+'</p>'+(r.excerpt?'<blockquote>'+E(r.excerpt)+'</blockquote>':'')+'<div>'+A('查看详情','bua-detail','data-index="'+r.index+'"')+' '+A('查看证据','bua-evidence','data-index="'+r.index+'"')+'</div></div>').join('')+'</section>').join('')+'<p class="bua-report-note">本清单供审计人员核查线索使用，最终认定需结合完整原始资料与业务凭证。</p></article>';}
function buaReport(t){return '<section class="bua-report"><div class="bua-report-toolbar"><span>根据本次返回结果整理</span><div>'+B('复制摘要','bua-copy-report','sm')+B('导出报告','bua-export-report','sm')+'</div></div>'+buaReportBody(t)+'</section>';}
resultContent=function(task){if(task.toolId!=='bidding')return buaBase.resultContent(task);const v=buaView(task);return '<div class="bua-result">'+buaHeader(task)+(v.tab==='files'?buaFiles(task):v.tab==='report'?buaReport(task):buaFindings(task))+'</div>';};
function buaSourceButtons(t,r){const ids=buaSources(t,r);return ids.length?ids.map(id=>{const d=file(id);return auditFileAccess(d).preview?A(E(d.name),'bua-source','data-id="'+E(id)+'"'): '<span class="bua-missing">'+E(d.name)+'（无原文预览权限）</span>';}).join(''):'<p class="bua-missing">该记录未注明具体来源文件，请核对任务资料与执行配置。</p>';}
function buaRawItems(r){return r.aiAnalysisItems||r.ai_analysis_items||r.detail?.ai_analysis_items||[];}
function buaEvidenceContext(e){const fields=[['证据类型',e.evidenceType],['排序方式',e.sortMethod],['输入预算',e.budget],['可用证据',e.totalAvailable],['实际使用',e.actualSent]].filter(([,v])=>v!==undefined&&v!==null&&v!=='');if(!e.summary&&!fields.length&&!(e.groups||[]).length)return '';return '<details class="bua-evidence-context"><summary>证据范围与补充信息</summary>'+(e.summary?'<p>'+E(e.summary)+'</p>':'')+'<dl>'+fields.map(([k,v])=>'<dt>'+k+'</dt><dd>'+E(String(v))+'</dd>').join('')+'</dl>'+(e.groups||[]).map(g=>'<h4>'+E(g.name||'')+'</h4><pre>'+E((g.items||[]).join('\n'))+'</pre><p>'+E(g.detail||'')+'</p>').join('')+'</details>';}
function buaExtractHTML(detail){if(!detail||typeof detail!=='object'||!Array.isArray(detail.sections))return '<pre class="bua-file-extract">'+E(typeof detail==='string'?detail:JSON.stringify(detail,null,2))+'</pre>';return (detail.warnings||[]).map(w=>'<p class="bua-restricted">'+E(w)+'</p>').join('')+detail.sections.map(section=>'<section class="bua-detail-section"><h3>'+E(section.title||'提取内容')+'</h3>'+(section.items||[]).map(item=>'<div class="bua-evidence-card">'+(item.type?'<small>'+E(item.type)+'</small>':'')+'<p>'+E(item.value||'未返回')+'</p>'+(item.sectionTitle?'<small>章节：'+E(item.sectionTitle)+'</small>':'')+(Number.isFinite(item.confidence)?'<small>置信度：'+Math.round(item.confidence*100)+'%</small>':'')+'</div>').join('')+'</section>').join('')+'<details class="bua-evidence-context"><summary>原始提取数据</summary><pre>'+E(JSON.stringify(detail,null,2))+'</pre></details>';}
function buaDetail(t,r){const row=buaRow(t,r,modalData.index),items=buaRawItems(r);return modalFrame('检查详情',E(row.project)+' · '+E(BUA_MODES[row.mode]),'<div class="bua-detail-meta">'+buaStatusMarkup(row)+'<span>置信度：'+E(buaConfidence(r))+'</span></div><h3 class="bua-detail-title">'+E(row.title)+'</h3><p class="bua-detail-rule">检查规则：'+E(row.rule)+(row.ruleId?'（'+E(String(row.ruleId))+'）':'')+'</p><section class="bua-detail-section"><h3>分析说明</h3><p>'+E(row.summary||'本条未返回分析说明，请结合原文核查。')+'</p></section>'+items.map(item=>'<section class="bua-detail-section"><h3>'+E(item.title||'分析事项')+'</h3><p>'+E(item.summary||'')+'</p>'+[['判断依据',item.judgmentBasis||item.judgment_basis],['可能的合理解释',item.reasonableExplanation||item.reasonable_explanation]].filter(([,text])=>text).map(([label,text])=>'<h4>'+label+'</h4><p>'+E(text)+'</p>').join('')+((item.inspectionItems||item.inspection_items||[]).length?'<h4>建议核查事项</h4><ul>'+(item.inspectionItems||item.inspection_items).map(s=>'<li>'+E(s)+'</li>').join('')+'</ul>':'')+((item.keyEvidence||item.key_evidence||[]).length?'<h4>关键证据</h4>'+ (item.keyEvidence||item.key_evidence).map(e=>'<blockquote><b>'+E(e.unit||'')+'</b><p>'+E(e.detail||'')+'</p>'+(e.location?'<small>'+E(e.location)+'</small>':'')+'</blockquote>').join(''):'')+'</section>').join('')+(row.excerpt?'<section class="bua-detail-section"><h3>返回的原文片段</h3><blockquote>'+E(row.excerpt)+'</blockquote></section>':'')+'<section class="bua-detail-section"><h3>核验来源</h3><div class="bua-source-links">'+buaSourceButtons(t,r)+'</div></section>',B('关闭','close-modal')+B('查看证据','bua-evidence','primary','data-index="'+row.index+'"'),'bua-detail-dialog medium');}
function buaEvidence(t,r){const e=r.llmEvidence||r.llm_evidence||{},list=r.evidenceList||r.evidence_list||Array.isArray(r.evidence)&&r.evidence||[],cards=e.cards||[];return modalFrame('原文证据',E(buaRow(t,r,modalData.index).rule),(r.excerpt?'<section class="bua-detail-section"><h3>原文片段</h3><blockquote>'+E(r.excerpt)+'</blockquote></section>':'')+list.map(item=>'<section class="bua-evidence-card"><h3>'+E(item.unit||'原文证据')+'</h3><p>'+E(item.detail||item.content||'')+'</p>'+(item.location?'<small>位置：'+E(item.location)+'</small>':'')+'</section>').join('')+cards.map(card=>'<section class="bua-evidence-card"><h3>'+E(card.fileName||(card.unitA&&card.unitB?card.unitA+' 与 '+card.unitB:card.id||'原文证据'))+'</h3>'+(card.cardType==='similarity'?'<div class="bua-evidence-compare"><div><h4>'+E(card.unitA||'资料一')+'</h4><small>'+E(card.fileA||'')+'</small><pre>'+E(card.contentA||'')+'</pre></div><div><h4>'+E(card.unitB||'资料二')+'</h4><small>'+E(card.fileB||'')+'</small><pre>'+E(card.contentB||'')+'</pre></div></div>':'<pre>'+E(card.content||'')+'</pre>')+(card.metadata?'<details><summary>文件元数据</summary><pre>'+E(JSON.stringify(card.metadata,null,2))+'</pre></details>':'')+'</section>').join('')+(!r.excerpt&&!list.length&&!cards.length?'<p class="bua-empty">本条未返回原文证据片段，请从下方资料核验。</p>':'')+'<section class="bua-detail-section"><h3>打开来源文件</h3><div class="bua-source-links">'+buaSourceButtons(t,r)+'</div></section>'+buaEvidenceContext(e),B('关闭','close-modal'),'bua-evidence-dialog medium');}
modalContent=function(){const t=currentTask();if(t?.toolId==='bidding'&&['bua-detail','bua-evidence'].includes(modal)){const r=t.result?.[modalData.index];if(!r||!buaReadable(t,r))return modalFrame('关联资料不可查看','','资料或权限已变化，当前不能显示此条结果内容。',B('关闭','close-modal'),'small');return modal==='bua-detail'?buaDetail(t,r):buaEvidence(t,r);}if(t?.toolId==='bidding'&&modal==='bua-file-info'){const d=file(modalData.id);if(!d||!auditFileAccess(d).read)return modalFrame('资料不可查看','','资料或权限已变化。',B('关闭','close-modal'),'small');const detail=t.fileExtracts?.[d.id]||t.file_extracts?.[d.id];return modalFrame('文件提取信息',E(d.name),'<p>'+E(buaFileRole(t,d.id))+'</p>'+(detail?buaExtractHTML(detail):'<p class="bua-reading-note">本次记录未保存单独的结构化提取结果，可查看原文件与解析内容。</p>')+'<div>'+A('查看原文与解析','bua-source','data-id="'+E(d.id)+'"')+' '+A('查看关联结果','bua-file-results','data-id="'+E(d.id)+'"')+'</div>',B('关闭','close-modal'),'medium');}return buaBase.modalContent();};
function buaPaint(){const box=$('#bua-result-list');if(box&&currentTask())box.innerHTML=buaFindingTable(currentTask());}
function buaReportText(t){const rows=buaRows(t);return '招投标审计核查清单\n'+t.name+'\n'+rows.map(r=>r.project+'｜'+r.title+'｜'+BUA_STATES[r.status]+'\n'+(r.summary||'未返回摘要')).join('\n\n');}
handleAction=function(action,el){if(!buaActive()&&!['bua-source'].includes(action))return buaBase.handleAction(action,el);const t=currentTask(),ds=el?.dataset||{},v=t?buaView(t):null;if(action==='bua-tab'){v.tab=ds.tab;render();return;}if(action==='bua-status'){v.status=ds.status;v.page=1;render();return;}if(action==='bua-page'){v.page+=Number(ds.step);buaPaint();return;}if(action==='bua-file-page'){v.filePage+=Number(ds.step);render();return;}if(action==='bua-reset'){Object.assign(v,{project:'all',mode:'all',status:'all',risk:'all',file:'all',query:'',page:1});render();return;}if(action==='bua-clear-file'){v.file='all';v.page=1;render();return;}if(['bua-detail','bua-evidence'].includes(action)){const r=t.result?.[Number(ds.index)];if(!r||!buaReadable(t,r))return toast('关联资料不可查看，当前无法打开该条结果。');openModal(action,{index:Number(ds.index)});return;}if(action==='bua-file-info'){openModal('bua-file-info',{id:ds.id});return;}if(action==='bua-file-results'){if(modal?.startsWith('bua-'))buaBase.closeModal();Object.assign(v,{tab:'findings',project:'all',mode:'all',status:'all',risk:'all',file:ds.id,page:1,query:''});render();return;}if(action==='bua-source'){const d=file(ds.id);if(!t||(t.ids||[]).indexOf(ds.id)<0||!d||!auditFileAccess(d).read||!auditFileAccess(d).preview)return toast('当前无法预览此来源文件。');if(['bua-detail','bua-evidence','bua-file-info'].includes(modal))buaSourceReturn={type:modal,data:structuredClone(modalData),task:t.id};return buaBase.handleAction('source',el);}if(action==='bua-copy-report'){const text=buaReportText(t);return navigator.clipboard?.writeText(text).then(()=>toast('摘要已复制。')).catch(()=>toast('浏览器未允许复制，可导出报告。'));}if(action==='bua-export-report'){if(!trCanDownload(t)||buaRows(t,'all',true).length!==buaRows(t).length)return toast('关联资料下载权限已变化，当前无法导出报告。');const html='<!doctype html><html lang="zh-CN"><meta charset="utf-8"><title>招投标审计核查清单</title><style>body{max-width:960px;margin:32px auto;font-family:Arial,sans-serif;line-height:1.8;color:#273b52}section{margin-top:24px}h3{border-bottom:1px solid #ddd}blockquote{background:#f4f7fb;padding:12px}button{display:none}</style><body>'+buaReportBody(t)+'</body></html>';download((t.name||'招投标分析')+'-核查清单.html',html,'text/html;charset=utf-8');return;}return buaBase.handleAction(action,el);};
closeModal=function(){if(modal==='source'&&buaSourceReturn){const back=buaSourceReturn;buaSourceReturn=null;buaBase.closeModal();if(currentTask()?.id===back.task)openModal(back.type,back.data);return;}return buaBase.closeModal();};
exportRows=function(t,scope='all'){if(t.toolId!=='bidding')return buaBase.exportRows(t,scope);return [['项目','分析环节','涉及单位','检查内容','检查规则','规则编号','核验状态','风险等级','置信度','分析说明','原文片段','关联来源'],...buaRows(t,scope,true).map(r=>[r.project,BUA_MODES[r.mode],r.unit,r.title,r.rule,r.ruleId,BUA_STATES[r.status],buaRiskText(r.raw),buaConfidence(r.raw),r.summary,r.excerpt,r.sources.map(id=>file(id)?.name).join('；')])];};
doExport=function(){const t=currentTask();if(t?.toolId!=='bidding')return buaBase.doExport();if(!trCanDownload(t))return toast('资料下载权限已变化，请重新核对。');if($('#export-format')?.value!=='json')return buaBase.doExport();const scope=$('#export-scope')?.value||'all',rows=buaRows(t,scope,true);if(!rows.length)return toast('该范围暂无可下载结果。');download((t.name||'招投标分析')+'-结果.json',JSON.stringify({task:t.name,scope:scope==='all'?'本次全部结果':file(scope)?.name,config:t.config,projects:t.projects,modes:t.modes,execution_config:t.configFragment,results:rows.map(r=>r.raw)},null,2),'application/json;charset=utf-8');closeModal();};
window.addEventListener('change',e=>{if(!buaActive()||!e.target.dataset.buaChange)return;e.stopImmediatePropagation();const v=buaView(currentTask()),key=e.target.dataset.buaChange;v[key]=key==='size'?Number(e.target.value):e.target.value;v.page=1;buaPaint();},true);
window.addEventListener('input',e=>{if(!buaActive()||e.target.dataset.buaInput!=='query')return;e.stopImmediatePropagation();const v=buaView(currentTask());v.query=e.target.value;v.page=1;buaPaint();},true);
render();
